ALTER TABLE `bucket_members` ADD `channels` text DEFAULT '{"medium":[],"webhooks":[]}' NOT NULL;--> statement-breakpoint
UPDATE `bucket_members` SET `channels` = json_object('medium', json(CASE WHEN json_type(`buckets`.`notifications_rules`, '$.medium') = 'array' THEN json_extract(`buckets`.`notifications_rules`, '$.medium') ELSE '[]' END), 'webhooks', json(CASE WHEN `bucket_members`.`role` = 'owner' AND json_type(`buckets`.`notifications_rules`, '$.webhooks') = 'array' THEN json_extract(`buckets`.`notifications_rules`, '$.webhooks') ELSE '[]' END)) FROM `buckets` WHERE `buckets`.`id` = `bucket_members`.`bucket_id` AND json_valid(`buckets`.`notifications_rules`);--> statement-breakpoint
UPDATE `buckets` SET `notifications_rules` = json_remove(`notifications_rules`, '$.medium', '$.webhooks') WHERE json_valid(`notifications_rules`);
